(() => {
  const ui=IndiaCoverage, esc=ui.escape;
  const story=ui.get(new URLSearchParams(location.search).get('id'));
  const root=document.querySelector('#story-page');
  if(!story){root.innerHTML='<section class="india-not-found"><h1>Story not found</h1><p>Choose a story from the India edition.</p><a class="primary" href="index.html#headlines">Browse the news</a></section>';return;}
  document.title=`${story.title} — nonpartisan.ink`;
  const view={lens:'alignment',filter:'all'};
  const methods= `<details class="india-method" id="assessment-method"><summary>How these framing assessments work <span aria-hidden="true">＋</span></summary><div><p>These are editorial inferences about individual articles, checked on ${indiaEdition.checked}. They are not Ground News ratings, party affiliations, factuality scores or a claim about a publisher’s entire output.</p><dl><dt>Opposition / critical</dt><dd>Coverage foregrounds criticism of the central government or accountability arguments compatible with opposition concerns. Critics may be independent civil-society actors.</dd><dt>Ruling party / official</dt><dd>The headline, sourcing or narrative favours the central authorities’ justification in a contested domestic story. Reporting an official statement alone is insufficient.</dd><dt>Mixed / contextual</dt><dd>Competing accounts, uncertainty or substantive context are retained without a demonstrated party preference.</dd><dt>Unclear</dt><dd>The material is limited or lacks a meaningful domestic party comparison. No party bias is inferred.</dd></dl><p>Bars count only the reports listed here, one per source family. Related angles are marked. They do not represent all media coverage. Confidence describes the framing inference, not whether the report is true. No high-confidence assessments are assigned in this small manual sample.</p><p>Coverage focus is a separate lens describing what the article foregrounds: rights and scrutiny, context and impacts, or an official response.</p></div></details>`;
  root.innerHTML=`<div class="india-breadcrumb"><a href="index.html#headlines">← India coverage</a><span>${esc(story.category)} / ${esc(story.place)}</span></div><section class="india-detail-hero"><div><div class="india-detail-kicker"><span>${esc(story.category)}</span><span>${esc(story.date)}</span></div><h1>${esc(story.title)}</h1><p class="india-detail-dek">${esc(story.dek)}</p><div class="india-detail-byline"><span>${story.reports.length} reviewed ${story.reports.length===1?'report':'reports'}</span><span>${esc(story.read)} read</span><span>Checked ${indiaEdition.checked}</span></div><div class="india-detail-actions"><a class="primary" href="#reporting">Compare the reports ↓</a><button class="outline" id="copy-story">Copy story link</button><span id="copy-status" role="status"></span></div></div>${ui.visual(story)}</section><div class="india-detail-layout"><div class="india-detail-main"><section class="india-brief"><span class="india-eyebrow">The story in brief</span><h2>What is being reported</h2><p>${esc(story.summary)}</p><div class="india-takeaway"><span>Keep in mind</span><p>${esc(story.takeaway)}</p></div><div class="india-reference-links">${story.ground?`<a href="${esc(story.ground)}" target="_blank" rel="noopener noreferrer">Ground News story collection ↗</a>`:''}${story.primary?`<a href="${esc(story.primary.url)}" target="_blank" rel="noopener noreferrer">${esc(story.primary.label)} ↗</a>`:''}</div></section><section class="india-claims"><div class="india-section-heading"><div><span class="india-eyebrow">Claims & context</span><h2>Separate the accounts</h2></div></div>${story.claims.map(claim=>`<div class="india-claim"><span class="claim-status ${claim.status.toLowerCase()}">${esc(claim.status)}</span><p>${esc(claim.text)}</p>${ui.sourceLink(story,claim,'Read the reporting ↗')}</div>`).join('')}</section>${story.perspectives.length?`<section class="india-perspectives"><span class="india-eyebrow">The competing positions</span><h2>Different voices, one story</h2><div>${story.perspectives.map(p=>`<article><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p>${ui.sourceLink(story,p,'Inspect the source ↗')}</article>`).join('')}</div></section>`:''}<section id="reporting" class="india-reporting"><div class="india-section-heading"><div><span class="india-eyebrow">Read across the coverage</span><h2>Tap a segment to see why</h2></div><span id="report-count"></span></div><p class="india-reporting-intro">Open each assessment for the evidence and reasoning, then inspect the original report.</p><div class="india-report-filters" id="report-filters"></div><div id="report-list" class="india-report-list" aria-live="polite"></div></section>${methods}</div><aside class="india-detail-aside"><section class="india-coverage-panel"><div class="india-panel-top"><span class="india-eyebrow">Coverage at a glance</span><a href="#assessment-method" aria-label="Read assessment methodology">ⓘ</a></div><h2>How it is framed</h2><div class="india-lens-switch" role="group" aria-label="Story coverage lens"><button data-story-lens="alignment" aria-pressed="true">Government framing</button><button data-story-lens="focus" aria-pressed="false">Coverage focus</button></div><div id="story-distribution"></div><p id="story-distribution-note"></p><a class="india-panel-link" href="#reporting">Explore the evidence ↓</a></section><section class="india-gaps"><span class="india-eyebrow">Questions still open</span><h3>What to look for next</h3><ul>${story.gaps.map(gap=>`<li>${esc(gap)}</li>`).join('')}</ul></section></aside></div><section class="india-related"><div class="india-section-heading"><h2>Keep widening the view</h2><a href="index.html#headlines">All India stories →</a></div><div>${indiaEdition.stories.filter(s=>s.id!==story.id).slice(0,3).map(s=>`<a href="${ui.path(s.id)}"><span>${esc(s.category)} · ${esc(s.date)}</span><h3>${esc(s.title)}</h3><span>${s.reports.length} reviewed ${s.reports.length===1?'report':'reports'} ↗</span></a>`).join('')}</div></section>`;
  function reportCard(report){
    const group=ui.groups[view.lens].find(g=>g.id===report[view.lens]);
    return `<article class="india-report-card" id="${esc(report.id)}"><div class="india-report-card-top"><span class="india-source-mark">${esc(report.initials)}</span><div><h3>${esc(report.publisher)}</h3><p>${esc(report.date)} 2026${report.host?` · via ${esc(report.host)}`:''}${report.language?` · ${esc(report.language)}`:''}</p></div><span class="india-assessment-tag ${group.tone}">${esc(group.label)}</span></div><h4>${esc(report.title)}</h4><div class="india-report-meta"><span>${esc(report.scope)}</span><span>${esc(report.access)}</span>${report.sourceRole?`<span>${esc(report.sourceRole)}</span>`:''}</div><details class="india-evidence" open><summary>Why this assessment <span>${esc(report.confidence)} confidence</span></summary><div><span class="india-evidence-label">Evidence paraphrase</span><p>${esc(report.evidence)}</p><span class="india-evidence-label">${view.lens==='alignment'?'Framing inference':'Party framing assessment'}</span><p>${esc(report.why)}</p><div class="india-voice"><span>Voices heard</span>${esc(report.voice)}</div></div></details><a class="india-original-link" href="${esc(report.url)}" target="_blank" rel="noopener noreferrer">Open original report <span aria-hidden="true">↗</span></a></article>`;
  }
  function render(){
    const grouped=ui.counts(story,view.lens);
    document.querySelector('#story-distribution').innerHTML=ui.bar(story,view.lens,true,view.filter)+`<div class="india-distribution-rows">${grouped.map(group=>`<button data-report-filter="${group.id}" aria-pressed="${view.filter===group.id}"><span><i class="${group.tone}"></i>${esc(group.label)}</span><strong>${group.count}<small> / ${story.reports.length}</small></strong></button>`).join('')}</div>`;
    document.querySelector('#story-distribution-note').textContent=view.lens==='alignment'?'Framing signals in this reviewed sample. Party allegiance is not established. Zero means no supporting assessment in this sample.':'Coverage emphasis is distinct from party allegiance. Each reviewed report has one primary focus.';
    document.querySelectorAll('[data-story-lens]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.storyLens===view.lens)));
    document.querySelector('#report-filters').innerHTML=`<button data-report-filter="all" aria-pressed="${view.filter==='all'}">All reports <span>${story.reports.length}</span></button>${grouped.map(group=>`<button data-report-filter="${group.id}" aria-pressed="${view.filter===group.id}"><i class="${group.tone}"></i>${esc(group.short)} <span>${group.count}</span></button>`).join('')}`;
    const reports=story.reports.filter(report=>view.filter==='all'||report[view.lens]===view.filter);
    document.querySelector('#report-count').textContent=`${reports.length} of ${story.reports.length} reports`;
    document.querySelector('#report-list').innerHTML=reports.length?reports.map(reportCard).join(''):`<div class="india-empty"><h3>No assessed reports in this group</h3><p>This sample contains no evidence supporting this category. Try another segment or view all reports.</p><button class="outline" data-report-filter="all">Show all reports</button></div>`;
  }
  root.addEventListener('click',event=>{
    const button=event.target.closest('button');if(!button)return;
    if(button.dataset.storyLens){view.lens=button.dataset.storyLens;view.filter='all';render();}
    if(button.dataset.reportFilter){view.filter=button.dataset.reportFilter;render();if(button.closest('.india-coverage-panel'))document.querySelector('#reporting').scrollIntoView({behavior:'smooth'});}
    if(button.id==='copy-story'){
      const status=document.querySelector('#copy-status');
      if(!navigator.clipboard){status.textContent='Copy the address from your browser.';return;}
      navigator.clipboard.writeText(location.href).then(()=>{status.textContent='Link copied';},()=>{status.textContent='Copy the address from your browser.';});
    }
  });
  render();
  if(location.hash) {
    const report=story.reports.find(report=>'#'+report.id===location.hash);
    if(report)document.getElementById(report.id)?.scrollIntoView({block:'center'});
  }
})();
